import random
secret = random.randint(1, 20)
tries = 0
while True:
    guess = int(input("O teu palpite: "))
    tries += 1
    if guess < secret:
        print("Mais alto")
    elif guess > secret:
        print("Mais baixo")
    else:
        print("Acertaste em", tries, "tentativas")
        break
